import json
with open('/app/resources/treasury_bulletin_1946_07.json', 'r') as f:
    data = json.load(f)

# Look for tables about Series E sales by state
def find_tables(d, path=''):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            results.extend(find_tables(v, f'{path}.{k}'))
    elif isinstance(d, list):
        for i, item in enumerate(d):
            results.extend(find_tables(item, f'{path}[{i}]'))
    elif isinstance(d, str):
        if 'Series E' in d or 'Series e' in d or 'payroll' in d.lower() or 'state' in d.lower():
            results.append(path)
    return results

results = find_tables(data)
for r in results[:20]:
    print(r)
